// Yu’s Daily Scope v7 — 原生比例布局版
// 整份替换旧脚本。大号显示 1–6 条，中号显示 7–9 条。
// 参数 theme=b 切换紫色。联网失败保留缓存。
// ---------------- ① 要确认的只有这两个地址 ----------------
const API_URL = "https://mstw666.github.io/Yu-s-Daily-Scope/data/briefing.json";
const WEB_URL = "https://mstw666.github.io/Yu-s-Daily-Scope/";

// App 里点 ▶ 预览时用哪个尺寸（不影响桌面上的组件）
const PREVIEW_FAMILY = "large";            // "large" 或 "medium"

// ---------------- ② 小组件参数 ----------------
const P = (function(){
  const out = {};
  String(args.widgetParameter || "").split("&").forEach(function(p){
    const kv = p.split("=");
    if (kv[0]) out[kv[0].trim()] = (kv[1] || "").trim();
  });
  return out;
})();
const THEME_KEY = String(P.theme || "a").toUpperCase() === "B" ? "B" : "A";

// ---------------- ③ 主题（与 tokens.json 同源） ----------------
const THEMES = {
  A: { bgDeep:"#071016", bgLight:"#0B222A",
       ink:"#EDF3EF", ink2:"#9DB6B2", dim:"#5F7A78",
       accent:"#63D3BF", amber:"#F1C489",
       card:new Color("#FFFFFF",0.045), hair:new Color("#FFFFFF",0.075),
       tile:"tile-a.png", bot:"bot-a.png" },
  B: { bgDeep:"#08070F", bgLight:"#181234",
       ink:"#F2EFFA", ink2:"#B4AAD2", dim:"#7A6F99",
       accent:"#A99BFF", amber:"#FFC98E",
       card:new Color("#FFFFFF",0.05), hair:new Color("#FFFFFF",0.09),
       tile:"tile-b.png", bot:"bot-b.png" }
};
const T = THEMES[THEME_KEY];

// ---------------- ④ 文案：优先用 GPT 写进 JSON 的 ----------------
const FALLBACK_MOTTO = "把好奇变成动作，把日常看成风景。";
function greeting(data){
  if (data && data.greeting) return data.greeting;
  const h = new Date().getHours();
  if (h < 11) return "小宇，早上好。";
  if (h < 14) return "小宇，中午好。";
  if (h < 18) return "小宇，下午好。";
  return "小宇，晚上好。";
}
function whisper(data, n){
  if (data && data.voice) return data.voice;
  return "我把今天捡回来了，一共 " + n + " 件。";
}
// ---------------- ⑤ 日期与状态 ----------------
function pad2(n){ return ("0" + n).slice(-2); }
function todayISO(){
  // 与网页一致，按北京时间判断「是不是今天」
  try {
    const s = new Intl.DateTimeFormat("sv-SE", {
      timeZone:"Asia/Shanghai", year:"numeric", month:"2-digit", day:"2-digit"
    }).format(new Date());
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  } catch(e){}
  const d = new Date(Date.now() + 8 * 3600000);
  return d.getUTCFullYear() + "-" + pad2(d.getUTCMonth()+1) + "-" + pad2(d.getUTCDate());
}
function formatToday(){
  const p = todayISO().split("-");
  const d = new Date(Number(p[0]), Number(p[1])-1, Number(p[2]));
  return Number(p[1]) + "月" + Number(p[2]) + "日 周" + "日一二三四五六"[d.getDay()];
}
function md(iso){
  if (!iso) return "";
  const p = String(iso).split("-");
  return p.length >= 3 ? Number(p[1]) + "/" + Number(p[2]) : String(iso);
}
// GPT 没给 date_label 时的兜底；字段名以线上 JSON 为准（date_end 不是 date_iso_end）
function dateLabel(it){
  if (it.date_label) return it.date_label;
  if (!it.date_iso || String(it.date_iso).indexOf("0000") === 0) return "日期待确认";
  switch (it.date_kind) {
    case "deadline":   return "截止 " + md(it.date_iso);
    case "exhibition": return "展至 " + md(it.date_iso);
    case "range":      return it.date_end ? md(it.date_iso) + "–" + md(it.date_end) : md(it.date_iso);
    default:           return md(it.date_iso);
  }
}
const CACHE_FILE = "yus-scope-cache.json";
function cacheTime(){
  try {
    const fm = FileManager.local();
    const c = JSON.parse(fm.readString(fm.joinPath(fm.documentsDirectory(), CACHE_FILE)));
    const d = new Date(c._fetchedAt);
    return isNaN(d.getTime()) ? "" : pad2(d.getHours()) + ":" + pad2(d.getMinutes());
  } catch(e){ return ""; }
}

// ---------------- ⑥ 数据加载 + 四态 ----------------
// state: live（今日已同步）| cache（断网用今日缓存）| stale（非今日）| error（无内容）
async function loadData(){
  const fm = FileManager.local();
  const cachePath = fm.joinPath(fm.documentsDirectory(), CACHE_FILE);
  let cached = null;
  if (P.reset === "1") {
    try { if (fm.fileExists(cachePath)) fm.remove(cachePath); } catch(e){}
  } else if (fm.fileExists(cachePath)) {
    try { cached = JSON.parse(fm.readString(cachePath)); } catch(e){}
  }
  try {
    const req = new Request(API_URL + "?t=" + Date.now());
    req.timeoutInterval = 12;
    req.headers = { "Cache-Control": "no-cache" };
    const json = await req.loadJSON();
    if (!json || !Array.isArray(json.items)) throw new Error("bad payload");
    json._fetchedAt = Date.now();
    fm.writeString(cachePath, JSON.stringify(json));
    // 关键：按数据里的 date 判断，而不是按抓取时间，和网页保持同一套语义
    return { data: json, state: json.date === todayISO() ? "live" : "stale" };
  } catch(e) {
    if (cached && cached.items && cached.items.length) {
      return { data: cached, state: cached.date === todayISO() ? "cache" : "stale" };
    }
    return { data: null, state: "error" };
  }
}

// v7: target canvas 338 × 354 / 338 × 158. Native text and tappable rows.
// Optional parameter width=378 for display zoom calibration; preview=medium for App preview.
const screen = Device.screenSize();
const shortSide = Math.min(screen.width, screen.height);
const widths = {320:292,360:306,375:321,390:338,393:338,402:344,414:360,428:364,430:364,440:378};
const widgetWidth = Number(P.width) >= 280 && Number(P.width) <= 500 ? Number(P.width) : (widths[shortSide] || Math.round(shortSide - 56));
const S = widgetWidth / 338;
const u = n => n * S;
const CONTENT = widgetWidth - u(26);
function text(parent, value, size, color, bold=false) {
  const t=parent.addText(String(value || ''));
  t.font=bold?Font.semiboldSystemFont(u(size)):Font.systemFont(u(size));
  t.textColor=new Color(color); t.lineLimit=1; t.minimumScaleFactor=0.85;
  return t;
}
function row(parent, height) {
  const s=parent.addStack(); s.layoutHorizontally(); s.centerAlignContent();
  s.size=new Size(CONTENT,u(height)); return s;
}
const ART={"atile":"","abot":"","btile":"","bbot":""};
const mark=Image.fromData(Data.fromBase64String(ART[THEME_KEY.toLowerCase()+"tile"]));
const robot=Image.fromData(Data.fromBase64String(ART[THEME_KEY.toLowerCase()+"bot"]));
function icon(parent,image,size){const i=parent.addImage(image);i.imageSize=new Size(u(size),u(size));}
function background(w){
  const g=new LinearGradient();g.locations=[0,0.35,1];
  g.colors=[new Color(THEME_KEY==='B'?'#25213B':'#1A3034'),new Color(T.bgDeep),new Color(T.bgLight)];
  g.startPoint=new Point(0,0);g.endPoint=new Point(0.9,1);w.backgroundGradient=g;
  w.setPadding(u(13),u(13),u(13),u(13));
}
function issueDate(data){
  const value=data && /^\d{4}-\d{2}-\d{2}$/.test(data.date)?data.date:todayISO();
  const p=value.split('-');const d=new Date(value+'T12:00:00+08:00');
  return Number(p[1])+'月'+Number(p[2])+'日 周'+'日一二三四五六'[d.getUTCDay()];
}
function header(w,data,state,medium){
  const h=row(w,medium?15:18);icon(h,mark,medium?15:18);h.addSpacer(u(8));
  if(medium){const b=h.addStack();b.borderColor=new Color(T.amber,0.3);b.borderWidth=0.5;b.cornerRadius=u(3);b.setPadding(0,u(3),0,u(3));text(b,'续',8,T.amber);h.addSpacer(u(7));}
  text(h,issueDate(data),11,T.ink,true);h.addSpacer();
  const dot=h.addStack();dot.size=new Size(u(4),u(4));dot.cornerRadius=u(2);
  dot.backgroundColor=new Color(state==='live'?T.accent:T.amber);h.addSpacer(u(4));
  text(h,state==='live'?(medium?cacheTime():'已同步'):state==='cache'?'离线缓存':state==='stale'?'非今日':'未连接',8,T.ink2);
  if(!medium){h.addSpacer(u(8));text(h,'↻',14,T.ink2);}
}
function item(w,it,index,lite,count){
  const height=lite?25:count>=5?34:count===4?43:48;
  const r=row(w,height);r.backgroundColor=T.card;r.cornerRadius=u(9);
  r.borderColor=T.hair;r.borderWidth=0.6;r.setPadding(0,u(9),0,u(9));
  r.url=WEB_URL+(THEME_KEY==='B'?'?theme=b':'');
  const number=r.addStack();number.size=new Size(u(21),0);
  text(number,String(index+1).padStart(2,'0'),11,T.dim,true);
  const label=dateLabel(it);
  const dateWidth=Math.min(100,Math.max(54,Array.from(label).reduce((a,c)=>a+(/[\u4e00-\u9fff]/.test(c)?9.3:5.2),0)+4));
  const mid=r.addStack();mid.layoutVertically();mid.size=new Size(CONTENT-u(18+21+8+dateWidth),0);mid.spacing=u(1);
  text(mid,it.title,lite?12:count>=5?11.8:14,T.ink);
  if(!lite)text(mid,it.summary||'',count>=5?9.2:10.5,T.ink2);
  r.addSpacer(u(8));const date=r.addStack();date.size=new Size(u(dateWidth),0);date.addSpacer();
  text(date,label,9.3,T.amber).rightAlignText();
}
function footer(w,data,medium){
  const f=row(w,10);const left=f.addStack();left.size=new Size(CONTENT-u(58),0);
  text(left,medium?'我盯着截止日，放心。':(data.quote||FALLBACK_MOTTO),8,medium?T.ink2:T.dim);
  f.addSpacer();text(f,'全部 '+data.items.length+' 条 ›',8.5,T.amber);
}
async function render(w,data,state,medium){
  background(w);header(w,data,state,medium);w.addSpacer(u(medium?9:12));
  if(!data||!data.items.length){text(w,'今天还没连上。',14,T.ink,true);w.addSpacer(u(6));text(w,'点开网页查看，稍后再试。',10,T.ink2);return;}
  const list=medium?data.items.slice(6,9):data.items.slice(0,6);
  if(!medium){const g=row(w,34);icon(g,robot,23);g.addSpacer(u(9));const col=g.addStack();col.layoutVertically();col.spacing=u(1);
    text(col,greeting(data),19,T.ink,true);text(col,whisper(data,list.length),9.6,T.ink2);w.addSpacer(u(12));}
  for(let i=0;i<list.length;i++){item(w,list[i],medium?i+6:i,medium,list.length);if(i<list.length-1)w.addSpacer(u(4));}
  if(!list.length)text(w,'上面就是全部了。',12,T.ink2);
  // No expanding spacer after a full list: reserve only the designed footer gap.
  if(!medium&&list.length<=3){w.addSpacer();const art=row(w,44);art.addSpacer();icon(art,robot,44);art.addSpacer();}
  w.addSpacer(u(medium?8:12));footer(w,data,medium);
}
const {data,state}=await loadData();
if(data&&data.items)data.items=data.items.slice().sort((a,b)=>String(a.date_iso||'9999').localeCompare(String(b.date_iso||'9999')));
const family=config.runsInWidget?(config.widgetFamily||'large'):(P.preview||PREVIEW_FAMILY);
const widget=new ListWidget();
await render(widget,data,state,family==='medium');
widget.url=WEB_URL+(THEME_KEY==='B'?'?theme=b':'');
widget.refreshAfterDate=new Date(Date.now()+25*60*1000);
if(config.runsInWidget)Script.setWidget(widget);
else if(family==='medium')await widget.presentMedium();
else await widget.presentLarge();
Script.complete();
